```sql
SELECT CAST(SUM(CASE WHEN Country = 'CZE' AND Segment = 'discount' THEN 1 ELSE 0 END) AS INTEGER) - SUM(CASE WHEN Country = 'SVK' AND Segment = 'discount' THEN 1 ELSE 0 END) AS more_discount_gas_stations;
```

```sql
SELECT publisher_id FROM alignment WHERE alignment = 'Star Trek';
```

```sql
SELECT m.major_name FROM member m WHERE m.first_name = 'Brent' AND m.last_name = 'Thomason';
```

```sql
SELECT AVG(CASE WHEN Sex = 'M' THEN (YEAR(NOW()) - YEAR(Birthday)) END) AS avg_age_male_cholsteroid;
```

```sql
SELECT COUNT(*) FROM posts WHERE Title = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer' AND ViewCount IS NOT NULL;
```

```sql
SELECT CAST(ROUND((COUNT(DISTINCT Id) WHERE YEAR(CreationDate) = '2011' AND Reputation > 1000) AS REAL) / COUNT(*) * 100, 2) as Percentage;
```

```sql
SELECT id FROM cards WHERE duelDeck = 'a';
```

```sql
SELECT MAX(height) as tallest_player;
FROM Player;
```

```sql
SELECT player_api_id, player_name, overall_rating FROM "Player_Attributes" WHERE strftime('%Y', date) = '2011' AND player_fifa_api_id = 847653;
```
